152	/**
153	 * A complete, valid props object for a given variation — narrows on `variation` with a plain
154	 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
155	 * index.tsx's own render body, not to test fixtures).
156	 *
157	 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
158	 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
159	 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
160	 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
161	 * present on every union member." A `test.each` call site passing a runtime (non-literal)
162	 * `variation` still resolves to the final, general overload below.
163	 */
164	function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
165	function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
166	function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
167	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
168	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
169	  const base = {
170	    id: 'p1',
171	    href: '/product/1',
172	    name: 'Natura Dress',
173	    headingLevel: 'h3' as const,
174	    primaryImage: PRIMARY,
175	  };
176	  switch (variation) {
177	    case 'wishlist':
178	      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
179	    case 'home':
180	      return { ...base, variation };
181	    case 'plp':
182	      return { ...base, variation };
183	    default:
184	      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
185	      // not silently falls through to a wrong variation's shape.
186	      return ((): never => {
187	        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
188	      })();
189	  }
190	}
191	
192	describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
193	  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
194	  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
195	  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
196	  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
